import {samplePatch,features,predict,quality,classify,Stabilizer,actionFor,roi} from './vision.js';
const $=id=>document.getElementById(id),canvas=$('view'),ctx=canvas.getContext('2d'),source=document.createElement('canvas'),sc=source.getContext('2d',{willReadFrequently:true}),video=$('video');
let model,demos,report,zones=[],results=[],frameReady=false,busy=false,drawing=false,startPoint=null,stream=null,loop=null,live=false,mediaUrl=null,demoIndex=0,original=null,ack=new Set(),lastMs=0,history=[],inputLabel='',mode='photo',sequence=0,objectUrls=[];
const stabilizer=new Stabilizer(3),pct=x=>(100*x).toFixed(1)+'%', colors={free:'#BDE77B',occupied:'#F3A96B',review:'#F6D873'},labels={free:'Свободно',occupied:'Занято',review:'Проверить'};
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',5000);}
function switchTab(id){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));$('pageName').textContent={monitor:'Площадка',evidence:'Проверка модели',business:'Экономика',about:'О проекте'}[id];}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function resetAnalysis(){results=[];ack.clear();stabilizer.clear();history=[];lastMs=0;sequence++;renderResults();}
function stop(){live=false;clearTimeout(loop);loop=null;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}video.pause();video.srcObject=null;$('stop').hidden=true;$('runState').textContent='Одиночный кадр';}
function setFrame(image){const w=image.videoWidth||image.naturalWidth||image.width,h=image.videoHeight||image.naturalHeight||image.height;const scale=Math.min(1,1920/w);source.width=Math.round(w*scale);source.height=Math.round(h*scale);sc.drawImage(image,0,0,source.width,source.height);canvas.width=source.width;canvas.height=source.height;frameReady=true;$('empty').style.display='none';$('frameSize').textContent=`${source.width} × ${source.height}`;draw();}
function draw(draft){ctx.clearRect(0,0,canvas.width,canvas.height);if(frameReady)ctx.drawImage(source,0,0);const line=Math.max(1.5,canvas.width/600);ctx.font=`600 ${Math.max(10,canvas.width/96)}px Arial`;
  zones.forEach((z,i)=>{const r=results.find(r=>r.id===z.id),c=colors[r?.state]||'#dae4d6';const[x,y,w,h]=z.box;ctx.fillStyle=c+'19';ctx.fillRect(x,y,w,h);ctx.strokeStyle=c;ctx.lineWidth=line;ctx.strokeRect(x,y,w,h);const text=z.id;const tw=ctx.measureText(text).width+8;ctx.fillStyle=c;ctx.fillRect(x,y,tw,Math.max(15,canvas.width/65));ctx.fillStyle='#20362a';ctx.fillText(text,x+4,y+Math.max(11,canvas.width/85));});
  if(draft){ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.setLineDash([6,4]);ctx.strokeRect(...draft);ctx.setLineDash([]);}}
async function loadDemo(i){stop();resetAnalysis();demoIndex=i;mode='photo';const d=demos[i];const img=new Image();img.src=d.file;await img.decode();original=img;setFrame(img);zones=d.zones.map(z=>({...z,box:[...z.box]}));inputLabel=d.original;$('feedName').textContent=`PKLot / ${d.name}`;$('inputTag').textContent='Открытый тестовый кадр';$('frameNote').textContent='Зоны из разметки. Ответы вычисляются по пикселям.';draw();await analyze();}
async function analyze(){if(busy||!model||!frameReady)return;if(!zones.length){toast('Добавьте хотя бы одну зону на кадре');return;}busy=true;$('analyze').disabled=true;const t=performance.now();try{
  const pixels=sc.getImageData(0,0,source.width,source.height),threshold=Number($('threshold').value)/100,now=performance.now();
  results=zones.map(z=>{const patch=samplePatch(pixels.data,source.width,source.height,z.box),q=quality(patch),p=predict(features(patch),model),raw=classify(p,q,z.box,threshold);const stable=live?stabilizer.update(z.id,raw,now):{state:raw,since:now,count:1};const elapsed=live?now-stable.since:0;return {id:z.id,name:z.name,kind:z.kind,box:z.box,probability:p,raw,state:stable.state,quality:q,elapsedMs:elapsed,pending:live&&raw!=='review'&&stable.count<3,action:actionFor(z,stable.state,elapsed,Number($('dwell').value))};});
  lastMs=performance.now()-t;history.push({at:new Date().toISOString(),ms:lastMs,free:results.filter(r=>r.state==='free').length,occupied:results.filter(r=>r.state==='occupied').length,review:results.filter(r=>r.state==='review').length});if(history.length>1000)history.shift();draw();renderResults();
}catch(e){toast('Не удалось обработать кадр: '+e.message);}finally{busy=false;$('analyze').disabled=false;}}
function renderResults(){for(const s of ['free','occupied','review'])$(s+'Count').textContent=results.length?results.filter(r=>r.state===s).length:'—';$('latency').replaceChildren(document.createTextNode(lastMs?lastMs.toFixed(0):'—'));const em=document.createElement('em');em.textContent='ms';$('latency').append(em);$('zoneCount').textContent=zones.length+' зон';$('device').textContent=lastMs?'CPU браузера · признаки + модель + правила':'Измеряется на вашем устройстве';
  $('zoneResults').replaceChildren();for(const r of results){const chip=document.createElement('button');chip.className='zone-chip '+r.state;chip.textContent=`${r.id} · ${r.pending?'Подтверждение…':labels[r.state]}`;chip.title=`P(занято) ${pct(r.probability)}; ${r.quality.reasons.join(', ')||'базовый контроль качества пройден'}`;chip.onclick=()=>toast(`${r.id}: ${labels[r.state]}. Оценка занятости ${pct(r.probability)}. ${r.quality.reasons.join(', ')||'Без выявленных дефектов качества'}. ${r.kind==='charging'?'Занятость не доказывает зарядку.':''}`);$('zoneResults').append(chip);}
  const actions=results.filter(r=>r.action&&!ack.has(r.id+':'+r.action.text));$('actionCount').textContent=actions.length;$('actions').replaceChildren();if(!actions.length){const p=document.createElement('p');p.className='quiet';p.textContent=results.length?'Нет неподтверждённых задач. Продолжайте наблюдение.':'Задачи появятся после анализа';$('actions').append(p);}
  actions.forEach(r=>{const row=document.createElement('div');row.className='task';const content=document.createElement('div'),b=document.createElement('b'),p=document.createElement('p'),btn=document.createElement('button');b.textContent=r.id+' · '+r.action.text;p.textContent=r.quality.reasons.join(' · ')||`Оценка занятости ${pct(r.probability)} · требуется сотрудник`;btn.textContent='Принято';btn.onclick=()=>{ack.add(r.id+':'+r.action.text);renderResults();};content.append(b,p);row.append(content,btn);$('actions').append(row);});}
$('analyze').onclick=analyze;$('demoSelect').onchange=e=>loadDemo(Number(e.target.value)).catch(e=>toast(e.message));$('threshold').oninput=e=>{$('thresholdLabel').textContent=e.target.value+'%';stabilizer.clear();ack.clear();analyze();};$('dwell').onchange=()=>{if(!Number.isFinite(Number($('dwell').value))||Number($('dwell').value)<1)$('dwell').value=30;analyze();};
$('addZone').onclick=()=>{if(!frameReady){toast('Сначала загрузите кадр');return;}drawing=!drawing;canvas.classList.toggle('drawing',drawing);$('addZone').textContent=drawing?'Зажмите и обведите место':'＋ Добавить зону';};
const point=e=>{const b=canvas.getBoundingClientRect();return [Math.max(0,Math.min(canvas.width,(e.clientX-b.left)*canvas.width/b.width)),Math.max(0,Math.min(canvas.height,(e.clientY-b.top)*canvas.height/b.height))];};
canvas.onpointerdown=e=>{if(!drawing)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);startPoint=point(e);};canvas.onpointermove=e=>{if(!startPoint)return;const p=point(e);draw([Math.min(startPoint[0],p[0]),Math.min(startPoint[1],p[1]),Math.abs(p[0]-startPoint[0]),Math.abs(p[1]-startPoint[1])]);};
canvas.onpointerup=e=>{if(!startPoint)return;const p=point(e),box=[Math.min(startPoint[0],p[0]),Math.min(startPoint[1],p[1]),Math.abs(p[0]-startPoint[0]),Math.abs(p[1]-startPoint[1])].map(Math.round);startPoint=null;drawing=false;canvas.classList.remove('drawing');$('addZone').textContent='＋ Добавить зону';if(box[2]<16||box[3]<16){toast('Зона слишком мала: минимум 16×16 пикселей');draw();return;}if(zones.length>=150){toast('Лимит прототипа — 150 зон');return;}let i=1;while(zones.some(z=>z.id===`Z${i}`))i++;zones.push({id:`Z${i}`,name:`Зона ${i}`,kind:$('zoneKind').value,box});resetAnalysis();draw();analyze();};canvas.onpointercancel=()=>{startPoint=null;draw();};
$('undoZone').onclick=()=>{zones.pop();resetAnalysis();draw();if(zones.length)analyze();};$('clearZones').onclick=()=>{zones=[];resetAnalysis();draw();};
$('saveZones').onclick=()=>download('baywatch-zones.json',{version:1,width:source.width,height:source.height,zones:zones.map(({truth,...z})=>z)});
$('loadZones').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('Слишком большой файл');const d=JSON.parse(await f.text());if(d.version!==1||d.width!==source.width||d.height!==source.height)throw Error('Размер кадра не совпадает с настройкой');if(!Array.isArray(d.zones)||d.zones.length>150)throw Error('Неверный список зон');const ids=new Set();for(const z of d.zones){if(typeof z.id!=='string'||z.id.length>16||ids.has(z.id)||!['parking','charging','restricted'].includes(z.kind)||!Array.isArray(z.box)||z.box.length!==4||!z.box.every(Number.isFinite)||z.box[0]<0||z.box[1]<0||z.box[2]<16||z.box[3]<16||z.box[0]+z.box[2]>source.width+1||z.box[1]+z.box[3]>source.height+1)throw Error('Некорректная зона');ids.add(z.id);}zones=d.zones.map(z=>({id:z.id,name:String(z.name||z.id).slice(0,50),kind:z.kind,box:z.box}));resetAnalysis();draw();analyze();}catch(err){toast(err.message);}e.target.value='';};
$('upload').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>200*1024*1024){toast('Лимит файла — 200 МБ');return;}stop();resetAnalysis();zones=[];demoIndex=-1;original=null;inputLabel=f.name;mediaUrl=URL.createObjectURL(f);objectUrls.push(mediaUrl);$('feedName').textContent=f.name;$('inputTag').textContent='Локальный файл';$('frameNote').textContent='Новый ракурс: обведите отдельные места. Кадр не отправляется на сервер.';try{if(f.type.startsWith('video/')){mode='video';video.src=mediaUrl;await new Promise((resolve,reject)=>{video.onloadeddata=resolve;video.onerror=()=>reject(Error('Видео не поддерживается браузером'));});setFrame(video);await video.play();live=true;stabilizer.clear();$('stop').hidden=false;$('runState').textContent='Видео · 1 кадр/сек';tick();}else{mode='photo';const img=new Image();img.src=mediaUrl;await img.decode();original=img;setFrame(img);toast('Кадр открыт. Добавьте зоны парковочных мест.');}}catch(err){toast(err.message);}renderResults();e.target.value='';};
async function tick(){if(!live)return;if(video.readyState>=2){setFrame(video);if(zones.length)await analyze();}if(video.ended){stop();toast('Видео завершено');return;}loop=setTimeout(tick,1000);}
$('camera').onclick=async()=>{try{stop();stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:false});video.srcObject=stream;await video.play();zones=[];resetAnalysis();demoIndex=-1;original=null;mode='camera';inputLabel='Camera';setFrame(video);live=true;$('feedName').textContent='Камера устройства';$('inputTag').textContent='Локальный поток';$('frameNote').textContent='Закрепите устройство и обведите места. При сдвиге камеры перенастройте зоны.';$('runState').textContent='Камера · 1 кадр/сек';$('stop').hidden=false;tick();}catch(err){toast('Камера недоступна: '+err.message);}};$('stop').onclick=stop;video.onpause=()=>{if(live&&mode==='video')stabilizer.clear();};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&live){stop();stabilizer.clear();toast('Наблюдение остановлено при скрытии вкладки. Таймер сброшен.');}});
$('export').onclick=()=>{if(!results.length){toast('Сначала выполните анализ');return;}download('baywatch-report.json',{app:'BayWatch',version:'1.0.0',model:model.version,at:new Date().toISOString(),input:inputLabel,mode,width:source.width,height:source.height,threshold:Number($('threshold').value)/100,inferenceMs:lastMs,device:navigator.userAgent,results,acknowledged:Array.from(ack),recentHistory:history,limitations:['Occupancy is not charging status','Unknown performance on new cameras and local vehicles','No night validation','Scores not calibrated for out-of-distribution input']});};
function showEvidence(){const m=report.metrics.test;const cards=[['Точность на тесте',pct(m.accuracy),`${m.n} размеченных мест`],['F1 занятости',pct(m.f1),'Порог 0.5, без отказов'],['Покрытие при 20/80',pct(m.coverage_20_80),'Только по оценке модели'],['Точность принятых',pct(m.accepted_accuracy_20_80),'Без фильтра качества']];$('evalStats').replaceChildren();for(const[a,b,c]of cards){const el=document.createElement('article');const s=document.createElement('span'),v=document.createElement('strong'),n=document.createElement('small');s.textContent=a;v.textContent=b;n.textContent=c;el.append(s,v,n);$('evalStats').append(el);}let html='<table class="eval-table"><tr><th>Камера</th><th>Мест</th><th>Accuracy</th><th>F1</th></tr>';for(const [cam,m]of Object.entries(report.camera_metrics))html+=`<tr><td>${cam}</td><td>${m.n}</td><td>${pct(m.accuracy)}</td><td>${pct(m.f1)}</td></tr>`;html+='</table>';html+=`<p class="hint">Обучение: ${report.frames.train} кадров. Валидация: ${report.frames.valid}. Тест: ${report.frames.test}. Baseline «всегда самый частый класс»: ${pct(report.majority_baseline_test_accuracy)}. Seed 42; выбор эпохи и температуры — только по validation.</p>`;$('evalTable').innerHTML=html;}
$('evaluateDemo').onclick=()=>{if(demoIndex<0||!results.length||!zones.every(z=>Number.isInteger(z.truth))){$('demoEvaluation').textContent='Выберите исходный PKLot-кадр и выполните анализ.';return;}let correct=0,accepted=0;for(const r of results){if(r.state==='review')continue;accepted++;if(Number(r.state==='occupied')===zones.find(z=>z.id===r.id).truth)correct++;}$('demoEvaluation').textContent=`Принято ${accepted}/${results.length}; верно ${correct}/${accepted}${accepted?' ('+pct(correct/accepted)+')':''}. Учтены текущий порог и фильтр качества.`;};
async function stress(type){if(!original||live){toast('Проверка доступна для статического кадра');return;}setFrame(original);if(type==='dark'){sc.fillStyle='rgba(0,0,0,0.95)';sc.fillRect(0,0,source.width,source.height);}else{const small=document.createElement('canvas');small.width=16;small.height=9;small.getContext('2d').drawImage(source,0,0,16,9);sc.drawImage(small,0,0,source.width,source.height);}stabilizer.clear();ack.clear();await analyze();$('stressResult').textContent=`${type==='dark'?'Искусственная темнота':'Искусственное размытие'}: ${results.filter(r=>r.state==='review').length}/${results.length} зон требуют проверки.`;$('frameNote').textContent='Искусственная деградация исходного кадра. Не измерение реальной ночи или дождя.';}
$('stressDark').onclick=()=>stress('dark');$('stressBlur').onclick=()=>stress('blur');$('restore').onclick=async()=>{if(!original)return;setFrame(original);stabilizer.clear();ack.clear();await analyze();$('stressResult').textContent='Исходный кадр восстановлен.';$('frameNote').textContent='Исходный кадр. Ответы модели вычисляются по пикселям.';};
function calc(){const ids=['roiEvents','roiMinutes','roiHourly','roiCost','roiSetup'];const v=ids.map(id=>Math.max(0,Number($(id).value)||0));const r=roi({events:v[0],minutes:v[1],hourly:v[2],cost:v[3],setup:v[4]});$('roiResults').innerHTML=`<p class="roi-big">$${r.net.toFixed(0)} <small style="font-size:13px;font-weight:400">/ месяц, сценарный эффект</small></p><p class="hint">Время в денежном эквиваленте: $${r.saved.toFixed(0)}. Окупаемость: ${r.payback===null?'нет при этих условиях':r.payback.toFixed(1)+' мес.'} Это расчёт, не результат пилота.</p>`;}['roiEvents','roiMinutes','roiHourly','roiCost','roiSetup'].forEach(id=>$(id).oninput=calc);calc();
window.addEventListener('beforeunload',()=>{stop();objectUrls.forEach(u=>URL.revokeObjectURL(u));});
(async()=>{try{[model,demos,report]=await Promise.all(['models/occupancy.json','data/demos.json','data/evaluation.json'].map(async p=>{const r=await fetch(p);if(!r.ok)throw Error('Не удалось загрузить '+p);return r.json();}));$('modelStatus').textContent='● Модель готова · CPU';showEvidence();await loadDemo(0);}catch(e){$('modelStatus').textContent='Ошибка загрузки';$('empty').textContent=e.message;toast(e.message);}})();
